// n8n Code node — "Shelf life & eat-by dates"
// Mode: Run Once for All Items
// Input: parsed K2 extraction { retailer, purchase_date, items[] }
// Output: { today, retailer, purchaseDate, items: [{ id, name, canonical, category, price, purchaseDate, storage, eatBy, daysLeft, freezerDays, staple, confidence }] }
//
// Abridged USDA FoodKeeper table: id -> [emoji, category, defaultStorage, pantryDays, fridgeDays, freezerDays, staple]
const FOODKEEPER = {"spinach":["🥬","produce","fridge",null,5,300,0],"lettuce":["🥬","produce","fridge",null,7,null,0],"kale":["🥬","produce","fridge",null,6,300,0],"strawberries":["🍓","produce","fridge",1,3,240,0],"blueberries":["🫐","produce","fridge",null,10,240,0],"raspberries":["🍓","produce","fridge",null,3,240,0],"grapes":["🍇","produce","fridge",null,7,240,0],"bananas":["🍌","produce","pantry",4,7,60,0],"apples":["🍎","produce","fridge",21,45,null,0],"avocados":["🥑","produce","pantry",4,5,null,0],"tomatoes":["🍅","produce","pantry",5,7,null,0],"cucumbers":["🥒","produce","fridge",null,7,null,0],"bell_pepper":["🫑","produce","fridge",null,8,240,0],"broccoli":["🥦","produce","fridge",null,5,300,0],"carrots":["🥕","produce","fridge",null,21,300,0],"onions":["🧅","produce","pantry",30,60,null,0],"garlic":["🧄","produce","pantry",30,60,null,1],"potatoes":["🥔","produce","pantry",30,60,null,0],"sweet_potatoes":["🍠","produce","pantry",21,null,null,0],"mushrooms":["🍄","produce","fridge",null,5,240,0],"zucchini":["🥒","produce","fridge",null,5,null,0],"asparagus":["🌱","produce","fridge",null,4,240,0],"green_beans":["🫛","produce","fridge",null,5,240,0],"lemons":["🍋","produce","fridge",7,21,null,0],"limes":["🍋","produce","fridge",7,21,null,0],"cilantro":["🌿","produce","fridge",null,5,null,0],"basil":["🌿","produce","fridge",3,3,null,0],"ginger":["🫚","produce","fridge",null,21,180,0],"corn":["🌽","produce","fridge",null,2,240,0],"celery":["🥬","produce","fridge",null,14,null,0],"cauliflower":["🥦","produce","fridge",null,7,240,0],"mango":["🥭","produce","pantry",4,5,240,0],"oranges":["🍊","produce","fridge",7,21,null,0],"cabbage":["🥬","produce","fridge",null,14,null,0],"salad_kit":["🥗","produce","fridge",null,4,null,0],"milk":["🥛","dairy","fridge",null,7,90,0],"oat_milk":["🥛","dairy","fridge",180,10,null,0],"eggs":["🥚","eggs","fridge",null,35,null,0],"butter":["🧈","dairy","fridge",null,60,270,1],"cheddar":["🧀","dairy","fridge",null,180,180,0],"mozzarella":["🧀","dairy","fridge",null,7,null,0],"parmesan":["🧀","dairy","fridge",null,180,null,0],"yogurt":["🥣","dairy","fridge",null,14,60,0],"cream_cheese":["🧀","dairy","fridge",null,30,null,0],"sour_cream":["🥣","dairy","fridge",null,21,null,0],"heavy_cream":["🥛","dairy","fridge",null,10,120,0],"chicken_breast":["🐔","meat","fridge",null,2,270,0],"chicken_thighs":["🍗","meat","fridge",null,2,270,0],"ground_beef":["🥩","meat","fridge",null,2,120,0],"steak":["🥩","meat","fridge",null,4,240,0],"pork_chops":["🍖","meat","fridge",null,4,150,0],"bacon":["🥓","meat","fridge",null,14,30,0],"sausage":["🌭","meat","fridge",null,2,60,0],"deli_turkey":["🥪","deli","fridge",null,14,60,0],"salmon":["🐟","seafood","fridge",null,2,90,0],"shrimp":["🦐","seafood","fridge",null,2,180,0],"tofu":["🧊","deli","fridge",null,30,150,0],"bread":["🍞","bakery","pantry",5,14,90,0],"tortillas":["🫓","bakery","pantry",7,30,180,0],"bagels":["🥯","bakery","pantry",5,7,90,0],"hummus":["🥣","deli","fridge",null,30,null,0],"salsa":["🥣","deli","fridge",null,7,null,0],"guacamole":["🥑","deli","fridge",null,2,null,0],"fresh_pasta":["🍝","deli","fridge",null,3,60,0],"orange_juice":["🧃","beverage","fridge",null,14,null,0],"frozen_peas":["🫛","frozen","freezer",null,null,240,0],"frozen_berries":["🫐","frozen","freezer",null,null,240,0],"ice_cream":["🍨","frozen","freezer",null,null,90,0],"frozen_pizza":["🍕","frozen","freezer",null,null,90,0],"rice":["🍚","pantry","pantry",730,null,null,1],"pasta":["🍝","pantry","pantry",730,null,null,1],"olive_oil":["🫒","pantry","pantry",365,null,null,1],"canned_beans":["🥫","pantry","pantry",730,null,null,1],"canned_tomatoes":["🥫","pantry","pantry",540,null,null,1],"oats":["🌾","pantry","pantry",365,null,null,1],"flour":["🌾","pantry","pantry",240,null,null,1],"sugar":["🍬","pantry","pantry",730,null,null,1],"peanut_butter":["🥜","pantry","pantry",180,null,null,1],"cereal":["🥣","pantry","pantry",180,null,null,1],"coffee":["☕","pantry","pantry",180,null,null,1],"chips":["🍿","pantry","pantry",60,null,null,1],"soy_sauce":["🍶","pantry","pantry",365,null,null,1],"stock":["🥫","pantry","pantry",365,null,null,1],"spices":["🧂","pantry","pantry",730,null,null,1],"quinoa":["🌾","pantry","pantry",365,null,null,1],"honey":["🍯","pantry","pantry",730,null,null,1],"coconut_milk":["🥥","pantry","pantry",730,null,null,1],"sparkling_water":["🫧","beverage","pantry",365,null,null,1]};
// category -> [emoji, defaultStorage, pantryDays, fridgeDays, freezerDays]
const CATEGORY_DEFAULTS = {"produce":["🥗","fridge",null,7,240],"dairy":["🥛","fridge",null,10,90],"eggs":["🥚","fridge",null,35,null],"meat":["🥩","fridge",null,2,180],"seafood":["🐟","fridge",null,2,90],"bakery":["🍞","pantry",5,14,90],"deli":["🥪","fridge",null,5,60],"beverage":["🧃","fridge",180,7,null],"frozen":["🧊","freezer",null,null,180],"pantry":["🥫","pantry",365,null,null]};
const ESTIMATED_PRICE = { produce: 2.99, dairy: 4.49, eggs: 4.79, meat: 8.99, seafood: 11.99, bakery: 4.49, deli: 5.49, beverage: 3.99, frozen: 5.99, pantry: 3.49 };

const input = $input.first().json;
const today = new Date().toISOString().slice(0, 10);
const purchaseDate = /^\d{4}-\d{2}-\d{2}$/.test(input.purchase_date || '') ? input.purchase_date : today;
const addDays = (iso, n) => { const d = new Date(iso + 'T00:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
const between = (a, b) => Math.round((new Date(b + 'T00:00:00') - new Date(a + 'T00:00:00')) / 86400000);

const items = (input.items || []).map((raw, i) => {
  const entry = raw.canonical && FOODKEEPER[raw.canonical] ? FOODKEEPER[raw.canonical] : null;
  const category = entry ? entry[1] : (CATEGORY_DEFAULTS[raw.category] ? raw.category : 'produce');
  const cd = CATEGORY_DEFAULTS[category];
  const storage = entry ? entry[2] : cd[1];
  const life = { pantry: entry ? entry[3] : cd[2], fridge: entry ? entry[4] : cd[3], freezer: entry ? entry[5] : cd[4] };
  const days = life[storage] ?? life.fridge ?? life.pantry ?? null;
  const eatBy = days == null ? null : addDays(purchaseDate, days);
  return {
    id: 'i' + i,
    name: raw.name || raw.raw_line,
    rawLine: raw.raw_line,
    canonical: entry ? raw.canonical : 'unknown',
    emoji: entry ? entry[0] : cd[0],
    category,
    quantity: Number(raw.quantity) || 1,
    unit: raw.unit || null,
    price: Number(raw.price) > 0 ? Number(raw.price) : ESTIMATED_PRICE[category],
    purchaseDate,
    storage,
    shelfLife: life,
    freezerDays: life.freezer,
    eatBy,
    daysLeft: eatBy ? between(today, eatBy) : null,
    staple: entry ? entry[6] === 1 : false,
    confidence: Number(raw.confidence) || 0,
    needsConfirm: (Number(raw.confidence) || 0) < 0.7,
  };
});

return [{ json: { today, retailer: input.retailer || null, purchaseDate, items } }];

// n8n Code node — "Build K2 dinners request"
// Mode: Run Once for All Items
// Input: output of "Shelf life & eat-by dates". Output: same payload plus { body } for the HTTP Request node.

const PROMPT = "You are a pragmatic home cook. Propose THREE different weeknight dinners that use up what is already in this kitchen, prioritising the items closest to their eat-by date.\n\nINVENTORY (canonical id: name — deadline (value)):\n{{INVENTORY_LINES}}\n\nFREE PANTRY STAPLES you may assume: salt, black pepper, olive oil, garlic, butter, rice, pasta, flour, sugar, soy sauce, vinegar, canned tomatoes, chicken stock, dried spices, honey.\n\nHard rules:\n- Every non-staple ingredient MUST be one of the canonical ids in the inventory above. Do not invent ingredients (no saffron, no ingredients \"you probably have\").\n- Each dinner should use at least two inventory items, favouring the soonest-expiring and most expensive ones.\n- 15–40 minutes, 2–4 servings, real technique, no fluff.\n\nReturn ONLY JSON:\n{\n  \"dinners\": [\n    {\n      \"id\": string,                       // kebab-case slug\n      \"title\": string,\n      \"emoji\": string,                    // one emoji\n      \"minutes\": number,\n      \"servings\": number,\n      \"ingredients\": [ { \"foodId\": string, \"key\": boolean, \"optional\": boolean } ],\n      \"staples\": string[],                // subset of the free staples list\n      \"steps\": string[]                   // 2–4 terse steps\n    }\n  ]\n}";

const data = $input.first().json;
const lines = data.items
  .filter((it) => !it.staple && it.canonical !== 'unknown')
  .sort((a, b) => (a.daysLeft ?? 99) - (b.daysLeft ?? 99))
  .map((it) => `- ${it.canonical}: ${it.name} — ${it.daysLeft == null ? 'no deadline' : it.daysLeft <= 0 ? 'eat TODAY' : it.daysLeft + ' days left'} ($${it.price.toFixed(2)})`)
  .join('\n');

return [{
  json: {
    ...data,
    body: {
      model: $env.K2_MODEL || 'kimi-k2-0905-preview',
      temperature: 0.4,
      max_tokens: 2500,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: 'You return strictly valid JSON and nothing else.' },
        { role: 'user', content: PROMPT.replace('{{INVENTORY_LINES}}', lines) },
      ],
    },
  },
}];

// n8n Code node — "Parse K2 dinners"
// Mode: Run Once for All Items
// Combines the K2 dinners response with the dated inventory from "Build K2 dinners request".

const res = $input.first().json;
const content = (((res.choices || [])[0] || {}).message || {}).content || '';
const cleaned = content.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
let parsed = { dinners: [] };
try { parsed = JSON.parse(cleaned); } catch (e) { /* scheduler falls back to freeze-or-eat decisions only */ }

const upstream = $('Build K2 dinners request').first().json;
return [{ json: { today: upstream.today, retailer: upstream.retailer, items: upstream.items, dinners: parsed.dinners || [] } }];

// n8n Code node — "Dollar-optimising scheduler"
// Mode: Run Once for All Items
//
// Input (from "Parse K2 dinners"): { items: [...dated items from "Shelf life & eat-by dates"], dinners: [...K2 dinners] }
// Output: one item { plan, decisions, summary, calendar, email } ready for Google Calendar + Gmail.
//
// Objective: one dinner per night for HORIZON nights, never use an item after its eat-by, maximise the
// dollar value of at-risk food eaten before it expires. Exact DP over (night, set of rescued items).

const HORIZON = 7;
const GROUNDING_THRESHOLD = 0.8;
const MAX_TRACKED = 16;
const STAPLES = new Set(['salt', 'black pepper', 'olive oil', 'garlic', 'butter', 'rice', 'pasta', 'flour', 'sugar', 'soy sauce', 'vinegar', 'canned tomatoes', 'chicken stock', 'dried spices', 'honey']);

const input = $input.first().json;
const items = input.items || [];
const dinners = (input.dinners || []).filter((d) => d && d.title && Array.isArray(d.ingredients));
const today = input.today || new Date().toISOString().slice(0, 10);

const addDays = (iso, n) => { const d = new Date(iso + 'T00:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
const money = (n) => '$' + n.toFixed(2);
const nice = (iso) => new Date(iso + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

// ---- grounding: verify every dinner against what is actually in the kitchen on night d ----
function ground(dinner, day) {
  const staples = (dinner.staples || []).filter((s) => STAPLES.has(s));
  let owned = staples.length, total = staples.length, keyMissing = false;
  const used = [], missing = [];
  for (const ing of dinner.ingredients) {
    const hits = items.filter((it) => it.canonical === ing.foodId && (it.daysLeft == null || it.daysLeft >= day));
    if (hits.length) { owned++; total++; hits.forEach((h) => used.push(h.id)); }
    else if (!ing.optional) { total++; missing.push(ing.foodId); if (ing.key) keyMissing = true; }
  }
  const score = total ? owned / total : 0;
  return { score, owned, total, missing, used, passes: !keyMissing && score >= GROUNDING_THRESHOLD };
}

// ---- at-risk items: perishable, not yet expired, expiring inside the horizon ----
const atRisk = items
  .filter((it) => !it.staple && it.daysLeft != null && it.daysLeft >= 0 && it.daysLeft < HORIZON)
  .sort((a, b) => b.price - a.price);
const tracked = atRisk.slice(0, MAX_TRACKED);
const bit = new Map(tracked.map((it, i) => [it.id, i]));
const value = (mask) => tracked.reduce((s, it, i) => (mask & (1 << i) ? s + it.price : s), 0);

const feasible = [];
for (let d = 0; d < HORIZON; d++) {
  feasible.push(dinners.map((dinner) => {
    const g = ground(dinner, d);
    if (!g.passes) return null;
    let mask = 0; const rescued = [];
    for (const id of g.used) if (bit.has(id)) { mask |= 1 << bit.get(id); rescued.push(id); }
    return { dinner, g, mask, rescued };
  }).filter(Boolean));
}

// ---- exact DP: layers[d] = Map(mask -> {value, prev, choice}) ----
const layers = [new Map([[0, { value: 0, prev: 0, choice: null }]])];
for (let d = 0; d < HORIZON; d++) {
  const next = new Map();
  for (const [mask, st] of layers[d]) {
    if (!next.has(mask) || next.get(mask).value < st.value) next.set(mask, { value: st.value, prev: mask, choice: null });
    for (const f of feasible[d]) {
      const gain = f.mask & ~mask;
      if (!gain) continue;
      const nm = mask | f.mask, v = st.value + value(gain);
      if (!next.has(nm) || next.get(nm).value < v) next.set(nm, { value: v, prev: mask, choice: f });
    }
  }
  layers.push(next);
}
let best = 0, bestV = -1;
for (const [m, st] of layers[HORIZON]) if (st.value > bestV) { bestV = st.value; best = m; }
const choices = new Array(HORIZON).fill(null);
for (let d = HORIZON, m = best; d > 0; d--) { const st = layers[d].get(m); choices[d - 1] = st.choice; m = st.prev; }

// zero-gain nights still get a grounded dinner, for variety
const usedTitles = new Set(choices.filter(Boolean).map((c) => c.dinner.title));
for (let d = 0; d < HORIZON; d++) {
  if (choices[d]) continue;
  const c = feasible[d].filter((f) => !usedTitles.has(f.dinner.title)).sort((a, b) => b.g.used.length - a.g.used.length || b.g.score - a.g.score)[0];
  if (c) { choices[d] = c; usedTitles.add(c.dinner.title); }
}

// ---- assemble plan, freeze-or-eat decisions, before/after numbers ----
const covered = new Set();
const plan = choices.map((c, d) => {
  const date = addDays(today, d);
  if (!c) return { day: d, date, title: null };
  const rescued = c.rescued.filter((id) => !covered.has(id));
  rescued.forEach((id) => covered.add(id));
  const saved = rescued.reduce((s, id) => s + (atRisk.find((it) => it.id === id) || { price: 0 }).price, 0);
  return { day: d, date, title: c.dinner.title, emoji: c.dinner.emoji || '🍽️', minutes: c.dinner.minutes, steps: c.dinner.steps || [],
    grounding: `Uses ${c.g.owned} of ${c.g.total} ingredients you own`, saved, rescues: rescued.map((id) => items.find((it) => it.id === id).name) };
});

const decisions = []; let frozen = 0, wasted = 0;
for (const it of atRisk) {
  if (covered.has(it.id)) continue;
  if (it.freezerDays && it.storage !== 'freezer') { decisions.push({ kind: 'freeze', item: it.name, by: it.eatBy, goodUntil: addDays(today, it.freezerDays), value: it.price }); frozen += it.price; }
  else { decisions.push({ kind: 'eat-now', item: it.name, by: it.eatBy, value: it.price }); wasted += it.price; }
}
const atRiskValue = atRisk.reduce((s, it) => s + it.price, 0);
const eaten = atRisk.filter((it) => covered.has(it.id)).reduce((s, it) => s + it.price, 0);

// "no plan" baseline: cook whatever comes first in the list, deadlines ignored, no repeats
const naiveCovered = new Set(); const naiveUsed = new Set();
for (let d = 0; d < HORIZON; d++) { const f = feasible[d].find((x) => !naiveUsed.has(x.dinner.title)); if (f) { naiveUsed.add(f.dinner.title); f.rescued.forEach((id) => naiveCovered.add(id)); } }
const wastedNoPlan = atRisk.filter((it) => !naiveCovered.has(it.id)).reduce((s, it) => s + it.price, 0);

const summary = { atRiskValue, eaten, frozen, wasted, wastedNoPlan, headline: `Without a plan: ${money(wastedNoPlan)} of this receipt goes in the bin. With Dining Car: ${money(wasted)}.` };

// ---- rows for Google Calendar (one eat-by alarm per perishable, one dinner event per night) ----
const calendar = [];
for (const it of items) if (!it.staple && it.eatBy && it.daysLeft >= 0) calendar.push({ kind: 'eat-by', title: `${it.emoji || '🥬'} ${it.name} — eat by`, date: it.eatBy, allDay: true, description: `Bought ${it.purchaseDate} for ${money(it.price)}. Stored in the ${it.storage}. Source: USDA FoodKeeper.` });
for (const n of plan) if (n.title) calendar.push({ kind: 'dinner', title: `${n.emoji} ${n.day === 0 ? 'Tonight' : 'Dinner'}: ${n.title}`, date: n.date, allDay: false, start: `${n.date}T18:30:00`, end: `${n.date}T19:30:00`, description: n.steps.join('\n') });
for (const dec of decisions) if (dec.kind === 'freeze') calendar.push({ kind: 'freeze', title: `🧊 Freeze the ${dec.item.toLowerCase()} today`, date: dec.by, allDay: true, description: `Frozen, it keeps until ${dec.goodUntil}.` });

// ---- summary email ----
const soon = items.filter((it) => !it.staple && it.daysLeft != null && it.daysLeft >= 0 && it.daysLeft < 7);
const tonight = plan[0];
const email = {
  subject: `${soon.length} items expire this week — tonight: ${tonight.title || 'nothing urgent'}`,
  text: [
    summary.headline, '',
    `Tonight: ${tonight.emoji || ''} ${tonight.title || '—'}${tonight.rescues && tonight.rescues.length ? ` (rescues ${money(tonight.saved)}: ${tonight.rescues.join(', ')})` : ''}`,
    tonight.grounding ? `  ${tonight.grounding}` : '', '',
    'Expiring this week:',
    ...soon.sort((a, b) => a.daysLeft - b.daysLeft).map((it) => `  ${it.emoji || '•'} ${it.name} — eat by ${nice(it.eatBy)} (${money(it.price)})`), '',
    ...(decisions.length ? ['Decisions:', ...decisions.map((d) => d.kind === 'freeze' ? `  🧊 Freeze the ${d.item.toLowerCase()} by ${nice(d.by)} — good until ${nice(d.goodUntil)}` : `  ⚠️ Eat the ${d.item.toLowerCase()} by ${nice(d.by)} or it's ${money(d.value)} in the bin`), ''] : []),
    'Rest of the week:',
    ...plan.slice(1).filter((n) => n.title).map((n) => `  ${nice(n.date)}: ${n.emoji} ${n.title}`),
  ].join('\n'),
};

return [{ json: { today, plan, decisions, summary, calendar, email } }];
